  if (imgCount1987 === 0) {
    console.log(`No images found for 1987-03-29. Found: ${imgCount1987}`);
    console.log("C1");
    return;
  } else {
    cloudCover1987 = img1987.get('CLOUD_COVER').getInfo();
    if (cloudCover1987 === null) {
      console.log("CLOUD_COVER property not found for 1987 image.");
      console.log("C3");
      return;
    }
  }

  // Filter for 2001
  const col2001 = collection
    .filterBounds(lagoHermoso)
    .filterDate(date2001_start, date2001_end);

  const img2001 = col2001.first(); // Get the first image in the collection for the day

  let cloudCover2001 = null;
  let imgCount2001 = col2001.size().getInfo();

  if (imgCount2001 === 0) {
    console.log(`No images found for 2001-02-15. Found: ${imgCount2001}`);
    console.log("C1");
    return;
  } else {
    cloudCover2001 = img2001.get('CLOUD_COVER').getInfo();
    if (cloudCover2001 === null) {
      console.log("CLOUD_COVER property not found for 2001 image.");
      console.log("C3");
      return;
    }
  }

  // 3. No pixel-level processing for cloud cover metadata, so C2 check not needed.
  // 4. Calculation and Comparison
  console.log(`1987-03-29 Images: ${imgCount1987}, Cloud Cover: ${cloudCover1987.toFixed(2)}%`);
  console.log(`2001-02-15 Images: ${imgCount2001}, Cloud Cover: ${cloudCover2001.toFixed(2)}%`);

  if (cloudCover1987 > cloudCover2001) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
